export function koreaPlaceLabelsGeoJson() {
  return {
    type: "FeatureCollection" as const,
    features: KOREA_PLACE_LABELS.map((p, i) => ({
      type: "Feature" as const,
      id: i,
      properties: {
        name: p.name,
        full: p.full,
        kind: p.kind,
      },
      geometry: {
        type: "Point" as const,
        coordinates: [p.lng, p.lat],
      },
    })),
  };
}
